def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_time, id, qty) sorted by price desc, then arrival_time
    sell_book = []  # list of (price, arrival_time, id, qty) sorted by price asc, then arrival_time
    resting_orders = {}  # id -> (side, price, qty, arrival_time) for tracking purposes
    arrival_time_counter = 0
    cancelled_ids = set()

    def add_to_book(side, price, order_id, qty, arrival_time):
        if side == 'buy':
            buy_book.append((price, arrival_time, order_id, qty))
            buy_book.sort(key=lambda x: (-x[0], x[1]))
        else:
            sell_book.append((price, arrival_time, order_id, qty))
            sell_book.sort(key=lambda x: (x[0], x[1]))
        resting_orders[order_id] = (side, price, qty, arrival_time)

    def match_order(side, price, order_id, qty, arrival_time, is_ioc_or_market):
        nonlocal trades, buy_book, sell_book

        remaining_qty = qty

        if side == 'buy':
            i = 0
            while i < len(sell_book) and remaining_qty > 0:
                sell_price, sell_arrival, sell_id, sell_qty = sell_book[i]

                if sell_price <= price:
                    trade_qty = min(remaining_qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])

                    remaining_qty -= trade_qty
                    new_sell_qty = sell_qty - trade_qty

                    if new_sell_qty == 0:
                        sell_book.pop(i)
                        del resting_orders[sell_id]
                        cancelled_ids.discard(sell_id)
                    else:
                        sell_book[i] = (sell_price, sell_arrival, sell_id, new_sell_qty)
                        resting_orders[sell_id] = ('sell', sell_price, new_sell_qty, sell_arrival)
                        i += 1
                else:
                    break
        else:  # sell
            i = 0
            while i < len(buy_book) and remaining_qty > 0:
                buy_price, buy_arrival, buy_id, buy_qty = buy_book[i]

                if buy_price >= price:
                    trade_qty = min(remaining_qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])

                    remaining_qty -= trade_qty
                    new_buy_qty = buy_qty - trade_qty

                    if new_buy_qty == 0:
                        buy_book.pop(i)
                        del resting_orders[buy_id]
                        cancelled_ids.discard(buy_id)
                    else:
                        buy_book[i] = (buy_price, buy_arrival, buy_id, new_buy_qty)
                        resting_orders[buy_id] = ('buy', buy_price, new_buy_qty, buy_arrival)
                        i += 1
                else:
                    break

        # If limit order, add remaining to book
        if not is_ioc_or_market and remaining_qty > 0:
            add_to_book(side, price, order_id, remaining_qty, arrival_time)

        return remaining_qty

    for order in orders:
        arrival_time_counter += 1

        if order[0] == 'limit':
            _, order_id, side, price, qty = order
            match_order(side, price, order_id, qty, arrival_time_counter, False)

        elif order[0] == 'ioc':
            _, order_id, side, price, qty = order
            match_order(side, price, order_id, qty, arrival_time_counter, True)

        elif order[0] == 'market':
            _, order_id, side, qty = order
            if side == 'buy':
                price = float('inf')
            else:
                price = 0
            match_order(side, price, order_id, qty, arrival_time_counter, True)

        elif order[0] == 'cancel':
            _, order_id = order
            if order_id in resting_orders:
                side, price, qty, arr_time = resting_orders[order_id]
                del resting_orders[order_id]
                cancelled_ids.add(order_id)

                if side == 'buy':
                    buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != order_id]
                else:
                    sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != order_id]

    return trades

